def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []

    def amount(token):
        if not token.isdigit():
            return None
        return int(token)

    for index, operation in enumerate(ops):
        parts = operation.split()
        success = False

        if len(parts) == 1 and parts[0] == "undo":
            if history:
                kind, data = history.pop()

                if kind == "open":
                    del accounts[data]
                elif kind == "deposit":
                    name, value = data
                    accounts[name]["balance"] -= value
                elif kind == "withdraw":
                    name, value = data
                    accounts[name]["balance"] += value
                elif kind == "transfer":
                    source, target, value = data
                    accounts[source]["balance"] += value
                    accounts[target]["balance"] -= value
                elif kind == "freeze":
                    accounts[data]["frozen"] = False
                else:  # unfreeze
                    accounts[data]["frozen"] = True

                success = True

        elif len(parts) == 3 and parts[0] == "open":
            _, name, raw_value = parts
            value = amount(raw_value)
            if value is not None and name not in accounts:
                accounts[name] = {"balance": value, "frozen": False}
                history.append(("open", name))
                success = True

        elif len(parts) == 3 and parts[0] == "deposit":
            _, name, raw_value = parts
            value = amount(raw_value)
            if value is not None and value > 0 and name in accounts:
                accounts[name]["balance"] += value
                history.append(("deposit", (name, value)))
                success = True

        elif len(parts) == 3 and parts[0] == "withdraw":
            _, name, raw_value = parts
            value = amount(raw_value)
            if (
                value is not None
                and value > 0
                and name in accounts
                and not accounts[name]["frozen"]
                and accounts[name]["balance"] >= value
            ):
                accounts[name]["balance"] -= value
                history.append(("withdraw", (name, value)))
                success = True

        elif len(parts) == 4 and parts[0] == "transfer":
            _, source, target, raw_value = parts
            value = amount(raw_value)
            if (
                value is not None
                and value > 0
                and source != target
                and source in accounts
                and target in accounts
                and not accounts[source]["frozen"]
                and accounts[source]["balance"] >= value
            ):
                accounts[source]["balance"] -= value
                accounts[target]["balance"] += value
                history.append(("transfer", (source, target, value)))
                success = True

        elif len(parts) == 2 and parts[0] == "freeze":
            _, name = parts
            if name in accounts and not accounts[name]["frozen"]:
                accounts[name]["frozen"] = True
                history.append(("freeze", name))
                success = True

        elif len(parts) == 2 and parts[0] == "unfreeze":
            _, name = parts
            if name in accounts and accounts[name]["frozen"]:
                accounts[name]["frozen"] = False
                history.append(("unfreeze", name))
                success = True

        if not success:
            rejected.append(index)

    return (
        {name: account["balance"] for name, account in accounts.items()},
        rejected,
    )
